		updateLatencyQuantileEstimate(service, TelemetryMetricNames.REMOTE_LATENCY_P50_NANOS_ACTUAL, 0.50,
				latencyNanos);
		updateLatencyQuantileEstimate(service, TelemetryMetricNames.REMOTE_LATENCY_P95_NANOS_ACTUAL, 0.95,
				latencyNanos);
